-- 널 검사로 고친다

private BooleanExpression ageBetweenGuard(Integer min, Integer max) {
    BooleanExpression goe = ageGoe(min);
    BooleanExpression loe = ageLoe(max);
    if (goe == null) return loe;
    if (loe == null) return goe;
    return goe.and(loe);
}

@Test
void 널_검사() {
    em.clear();
    System.out.println("둘 다:   " + ageBetweenGuard(20, 30));
    System.out.println("앞 없음: " + ageBetweenGuard(null, 30));
    System.out.println("뒤 없음: " + ageBetweenGuard(20, null));
    System.out.println("둘 없음: " + ageBetweenGuard(null, null));
}

둘 다:   member1.age >= 20 && member1.age <= 30
앞 없음: member1.age <= 30
뒤 없음: member1.age >= 20
둘 없음: null

