private BooleanExpression ageBetween(Integer min, Integer max) {
    return Expressions.allOf(ageGoe(min), ageLoe(max));
}

@Test
void allOf() {
    System.out.println("둘 다:   " + ageBetween(20, 30));
    System.out.println("앞 없음: " + ageBetween(null, 30));
    System.out.println("뒤 없음: " + ageBetween(20, null));
    System.out.println("둘 없음: " + ageBetween(null, null));
}

