private BooleanExpression nameOrTeam(String name) {
    return Expressions.anyOf(usernameEq(name), teamNameEq(name));
}

@Test
void anyOf() {
    em.clear();
    queryFactory
            .select(member.username)
            .from(member)
            .leftJoin(member.team, team)
            .where(nameOrTeam("teamA"))
            .fetch()
            .forEach(System.out::println);
}

