private BooleanExpression ageBetweenBad(Integer min, Integer max) {
    BooleanExpression e = Expressions.TRUE;
    if (min != null) e = e.and(member.age.goe(min));
    if (max != null) e = e.and(member.age.loe(max));
    return e;
}

@Test
